class Solution {public:
 int minSwaps(vector<int>& nums){
  int n=nums.size(),odd=0;for(int x:nums)odd+=abs(x)%2;
  if(abs(2*odd-n)>1)return -1;
  auto solve=[&](int start){long long cost=0;int slot=0;
   for(int i=0;i<n;++i)if(abs(nums[i])%2==start){cost+=abs(i-2*slot);++slot;}
   return (int)cost;
  };
  if(2*odd>n)return solve(1);if(2*odd<n)return solve(0);
  return min(solve(0),solve(1));
 }
};
